import sys

def fwht(a):
    n = len(a)
    length = 1
    while length < n:
        step = length * 2
        for i in range(0, n, step):
            for j in range(i, i + length):
                x = a[j]
                y = a[j + length]
                a[j] = x + y
                a[j + length] = x - y
        length = step

def main():
    input = sys.stdin.readline
    H, W = map(int, input().split())
    n = 1 << W

    freq = [0] * n
    for _ in range(H):
        s = input().strip()
        mask = int(s, 2)
        freq[mask] += 1

    cost = [0] * n
    for mask in range(n):
        k = mask.bit_count()
        cost[mask] = min(k, W - k)

    fwht(freq)
    fwht(cost)

    conv = [freq[i] * cost[i] for i in range(n)]
    fwht(conv)

    ans = min(v // n for v in conv)
    print(ans)

if __name__ == "__main__":
    main()
